 * So this reader answers instead of throwing. `readable: false` means the caller's
 * policy could not be read, and the only honest thing it can do is what the
 * default `issue` mode does: open the pull request and stop for a person.
 */
export function tryGetUpdateConflictPolicy(): { agent: string; readable: boolean } {
  try {
    return {
      agent: getNewReleaseMode() === "pr-agent" ? getUpdateConflictAgent() : "",
      readable: true,
    };
  } catch {
    return { agent: "", readable: false };
  }
}
